<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { http } from "@/utils/http";
type Ledger = { id: string; name: string; baseCurrency?: string; archived?: boolean; createdAt?: string };
type Account = { id: string; name: string; type?: string; currency?: string; balance?: number; archived?: boolean };
type Transaction = { id: string; type?: string; amount?: number; currency?: string; occurredAt?: string; payee?: string; category?: string };
const ledgers = ref<Ledger[]>([]); const accounts = ref<Account[]>([]); const transactions = ref<Transaction[]>([]); const selected = ref<Ledger | null>(null); const loading = ref(false); const error = ref(""); const dialog = ref(false); const form = ref({ name: "", baseCurrency: "CNY" }); const hidden = ref(false);
const total = computed(() => accounts.value.reduce((sum, item) => sum + Number(item.balance || 0), 0));
async function load() { loading.value = true; error.value = ""; try { const result = await http.get<unknown, unknown>("/finance/ledgers"); ledgers.value = Array.isArray(result) ? result as Ledger[] : []; selected.value = selected.value || ledgers.value.find(item => !item.archived) || null; if (selected.value) { const [a, t] = await Promise.all([http.get<unknown, unknown>(`/finance/ledgers/${selected.value.id}/accounts`), http.get<unknown, unknown>(`/finance/ledgers/${selected.value.id}/transactions`)]); accounts.value = Array.isArray(a) ? a as Account[] : []; transactions.value = Array.isArray(t) ? t as Transaction[] : []; } } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "财务数据加载失败"; } finally { loading.value = false; } }
async function selectLedger(item: Ledger) { selected.value = item; await load(); }
async function createLedger() { if (!form.value.name.trim()) { error.value = "账本名称不能为空"; return; } try { await http.post("/finance/ledgers", { data: { name: form.value.name.trim(), baseCurrency: form.value.baseCurrency } }); dialog.value = false; form.value = { name: "", baseCurrency: "CNY" }; await load(); } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "账本创建失败"; } }
onMounted(load);
</script>
<template><main class="p-4 md:p-6"><div class="flex justify-between items-start gap-4 mb-6"><div><h1 class="text-2xl font-semibold">账本总览</h1><p class="mt-1 text-[var(--el-text-color-secondary)]">管理私密财务数据，金额仅在当前授权范围内展示。</p></div><div class="flex gap-2"><el-select v-model="selected" value-key="id" placeholder="选择账本" @change="selectLedger"><el-option v-for="item in ledgers" :key="item.id" :label="item.name" :value="item"/></el-select><el-button @click="dialog = true">新建账本</el-button><el-button :loading="loading" @click="load">刷新</el-button></div></div><el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="mb-4"/><el-skeleton v-if="loading" :rows="10" animated/><template v-else><el-empty v-if="!selected" description="暂无账本，先创建一个账本"/><template v-else><section class="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6"><el-card shadow="never"><div class="text-sm text-[var(--el-text-color-secondary)]">净资产 / 余额</div><div class="text-2xl font-semibold mt-2">{{ hidden ? '••••' : `${total.toFixed(2)} ${selected.baseCurrency || ''}` }}</div><el-button link class="mt-2" @click="hidden = !hidden">{{ hidden ? '显示金额' : '隐藏金额' }}</el-button></el-card><el-card shadow="never"><div class="text-sm text-[var(--el-text-color-secondary)]">账户数</div><div class="text-2xl font-semibold mt-2">{{ accounts.length }}</div></el-card><el-card shadow="never"><div class="text-sm text-[var(--el-text-color-secondary)]">本期收入</div><div class="text-2xl font-semibold mt-2">{{ hidden ? '••••' : '待统计' }}</div></el-card><el-card shadow="never"><div class="text-sm text-[var(--el-text-color-secondary)]">本期支出</div><div class="text-2xl font-semibold mt-2">{{ hidden ? '••••' : '待统计' }}</div></el-card></section><div class="grid grid-cols-1 lg:grid-cols-3 gap-5"><el-card shadow="never"><template #header>账户余额</template><el-empty v-if="!accounts.length" description="暂无账户"/><div v-for="account in accounts" :key="account.id" class="flex justify-between py-3 border-b last:border-0"><span>{{ account.name }}</span><span>{{ hidden ? '••••' : `${account.balance ?? 0} ${account.currency || ''}` }}</span></div></el-card><el-card shadow="never" class="lg:col-span-2"><template #header>最近交易</template><el-empty v-if="!transactions.length" description="暂无交易"/><el-table v-else :data="transactions.slice(0, 10)" stripe><el-table-column prop="occurredAt" label="日期" min-width="170"/><el-table-column prop="type" label="类型" width="110"/><el-table-column prop="payee" label="收付款方" min-width="160"/><el-table-column prop="category" label="分类" min-width="130"/><el-table-column label="金额" min-width="140"><template #default="{ row }">{{ hidden ? '••••' : `${row.amount ?? 0} ${row.currency || selected.baseCurrency || ''}` }}</template></el-table-column></el-table></el-card></div></template></template><el-dialog v-model="dialog" title="新建账本" width="420px"><el-form label-position="top"><el-form-item label="名称" required><el-input v-model="form.name"/></el-form-item><el-form-item label="基础币种" required><el-input v-model="form.baseCurrency"/></el-form-item></el-form><template #footer><el-button @click="dialog = false">取消</el-button><el-button type="primary" @click="createLedger">创建</el-button></template></el-dialog></main></template>
